package com.phoenix.business.web; import com.phoenix.business.domain.*;import com.phoenix.business.repository.*;import com.phoenix.business.service.AuditService;import com.phoenix.business.web.dto.PaymentResponse;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import lombok.RequiredArgsConstructor;import org.springframework.data.domain.*;import org.springframework.data.web.PageableDefault;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.time.*;import java.util.*;
@RestController @RequestMapping("/api/members") @RequiredArgsConstructor public class MemberController {private final MemberRepository repo;private final MembershipPlanRepository plans;private final PaymentRepository payments;private final AttendanceRepository attendance;private final AuditService audit;record Input(@NotBlank @Size(max=30)String memberCode,@NotBlank @Size(max=160)String name,@Size(max=30)String phone,@Email @Size(max=160)String email,String gender,LocalDate dateOfBirth,String address,String emergencyContact,@NotNull LocalDate joinDate,Long planId,LocalDate membershipStartDate,LocalDate expiryDate,Member.Status status,String notes){}@GetMapping public Page<Member> list(@RequestParam(required=false)String q,@RequestParam(required=false)Member.Status status,@PageableDefault(size=20,sort="name")Pageable p){return repo.search(blank(q),status,p);}@GetMapping("/{id}")public Member get(@PathVariable Long id){return repo.findById(id).orElseThrow();}@GetMapping("/{id}/profile")public Map<String,Object> profile(@PathVariable Long id){Member m=get(id);return Map.of("member",m,"payments",payments.findByMemberIdOrderByPaymentDateDesc(id).stream().map(PaymentResponse::from).toList(),"recentAttendance",attendance.findTop10ByMemberIdOrderByCheckedInAtDesc(id));}@PostMapping public Member create(@Valid @RequestBody Input q){Member m=new Member();copy(m,q);m=repo.save(m);audit.record("MEMBER_CREATED","MEMBER",m.getId(),m.getMemberCode()+" "+m.getName());return m;}@PutMapping("/{id}")public Member update(@PathVariable Long id,@Valid @RequestBody Input q){Member m=get(id);copy(m,q);m=repo.save(m);audit.record("MEMBER_UPDATED","MEMBER",id,m.getMemberCode()+" "+m.getName());return m;}@DeleteMapping("/{id}")@PreAuthorize("hasAnyRole('OWNER','ADMIN')")public void delete(@PathVariable Long id){Member m=get(id);repo.delete(m);audit.record("MEMBER_DELETED","MEMBER",id,m.getMemberCode());}private void copy(Member m,Input q){Long id=m.getId()==null?0:m.getId();if(q.email()!=null&&repo.existsByEmailIgnoreCaseAndIdNot(q.email(),id))throw new IllegalArgumentException("Email already belongs to another member");if(q.phone()!=null&&repo.existsByPhoneAndIdNot(q.phone(),id))throw new IllegalArgumentException("Phone already belongs to another member");m.setMemberCode(q.memberCode().trim());m.setName(q.name().trim());m.setPhone(blank(q.phone()));m.setEmail(blank(q.email()));m.setGender(blank(q.gender()));m.setDateOfBirth(q.dateOfBirth());m.setAddress(blank(q.address()));m.setEmergencyContact(blank(q.emergencyContact()));m.setJoinDate(q.joinDate());m.setPlan(q.planId()==null?null:plans.findById(q.planId()).orElseThrow());m.setMembershipStartDate(q.membershipStartDate());m.setExpiryDate(q.expiryDate());m.setStatus(q.status()==null?Member.Status.ACTIVE:q.status());m.setNotes(blank(q.notes()));}private String blank(String s){return s==null||s.isBlank()?null:s.trim();}}
